			//불러오기 활성화 이벤트
			function setDtlStts(msCrudType){
			    
			    sMsCrudType = msCrudType;

			    if(msCrudType == "READ") {
			        util.Control.setEnable(app, false, ["btnCallPlanHstr"]);
			    } else if(msCrudType == "UPDATE") {
			        //20221119-강화영-테스트
			        try {
			            util.Control.setEnable(app, true , ["btnCallPlanHstr"]);

			            var nRowCnt = util.Grid.getRowCount(app, "grdCasePlanList");            
			            if(nRowCnt == 0) {
			                util.Control.setReadOnly(app, true , "grpCasePlanDetail");
			            } else {
			                util.Control.setReadOnly(app, false, "grpCasePlanDetail");
			            }

			        } catch(e){
			            console.log(e);
			        }        
			    }

			    if(vcEmbDefInfo == null) {
			        vcEmbDefInfo = app.lookup("embapp2");
			    }

			    if(vcEmbDefInfo.hasAppMethod("setDtlStts")) { vcEmbDefInfo.callAppMethod("setDtlStts", msCrudType);}

			    app.lookup("cmnAutoHeightTextarea4").focus();
			}
			exports.setDtlStts = setDtlStts;

			//화면 하단 '취소'버튼 클릭시 DS를 REVERT처리
			function setRevert(){

			    app.lookup("dsCasePlanList").revert();
			    app.lookup("dsGoalPlanCn")  .revert();
			    app.lookup("dsProgramList") .revert();

			    setDsCasePlanRowCnt();
			    setDsProgMainRowCnt();

			    onCmbServiceTypeSelectionChange();

			    if(vcEmbDefInfo == null) {
			        vcEmbDefInfo = app.lookup("embapp2");
			    }

			    if(vcEmbDefInfo.getEmbeddedAppInstance() != null) {
			        vcEmbDefInfo.getEmbeddedAppInstance().getAllDataControls().forEach(function(ctrl) {
			            if(ctrl.type == "dataset") {
			                ctrl.revert();
			            }
			        });
			    }
			    
			    if(untTaskwk == "U09" || untTaskwk == "U10")
			        util.Grid.selectRow(app, "grdCasePlanList", 0);
			    else
			        util.Grid.selectRow(app, "grdCasePlanList", 0, false);
			}
			exports.setRevert = setRevert;

			/**
			 * 목록 데이터 조회 서브미션 호출
			 * @param psStatus - 조회 상태(저장 후 조회인 경우에는 'save' 구분값 넘김)
			 */
			function doList(psStatus) {

			    util.DataSet.clear(app, "dsCasePlanList");
			    util.DataSet.clear(app, "dsGoalPlanCn");
			    util.DataSet.clear(app, "dsProgramList");

			    setSrvcExcnBizView();

			    //조회 서브미션 호출
			    util.Submit.send(app, "subList", function(pbSuccess) {
			        if (pbSuccess) {

			            setDsCasePlanRowCnt();

			            //사례계획 목표계획내용 조회 서브미션 호출
			            util.Submit.send(app, "subGoalPlanCn", function(pbSuccess) {

			                //재조회시 서브화면 재조회 이벤트
			                callDetailList();

			                if (psStatus == "save") {
			                    //갱신된 데이터가 조회되었습니다.
			                    util.Msg.notify(app, "INF-M005");
			                } else {
			                    //조회되었습니다.
			                    util.Msg.notify(app, "INF-M001");
			                }

			                util.Control.redraw(app, "grpCasePlanList");
			                util.Control.redraw(app, "grpGoalPlanCn");
			                util.Control.redraw(app, "grpCasePlanDetail");
			    
			                util.Grid.selectRow(app, "grdCasePlanList", 0, false);

			                onCmbServiceTypeSelectionChange();
			            });
			        }
			    });
			}

			function callDetailList() {

			    console.log("callDetailList.sCaseMngNo=[" + sCaseMngNo + "]", "sCaseMngOdrno=[" + sCaseMngOdrno + "]");

			    if(!ValueUtil.isNull(sCaseMngNo) && !ValueUtil.isNull(sCaseMngOdrno)) {
			        if(vcEmbDefInfo == null) {
			            vcEmbDefInfo = app.lookup("embapp2");
			        }

			        if(vcEmbDefInfo.hasAppMethod("callList")){
			            console.log("callList_callDetailList.sCaseMngNo=[" + sCaseMngNo + "]", "sCaseMngOdrno=[" + sCaseMngOdrno + "]");
			            vcEmbDefInfo.callAppMethod("callList", sCaseMngNo, sCaseMngOdrno);      
			        }
			    }
			}

			function setFilterProgrmDs() {

			    var nIdx = util.Grid.getIndex(app, "grdCasePlanList");

			    var sCaseMngNo      = util.Grid.getCellValue(app, "grdCasePlanList", "CASE_MNG_NO"        , nIdx); //사례관리번호
			    var sCaseMngOdrno   = util.Grid.getCellValue(app, "grdCasePlanList", "CASE_MNG_ODRNO"     , nIdx); //사례관리차수
			    var sSrvcPvsnPlanNo = util.Grid.getCellValue(app, "grdCasePlanList", "SRVC_PVSN_PLAN_NO"  , nIdx); //서비스제공계획번호
			    var sResrceNo       = util.Grid.getCellValue(app, "grdCasePlanList", "RESRCE_NO"          , nIdx); //자원번호
			    var sRowIdx         = util.Grid.getCellValue(app, "grdCasePlanList", "CASE_PLAN_ROW_INDEX", nIdx);

			    var objDs = app.lookup("dsProgramList");
			    var sCondition = null;
			        sCondition = "CASE_MNG_NO == '" + sCaseMngNo +"' && CASE_MNG_ODRNO == '" + sCaseMngOdrno + "' && RESRCE_NO == '" + sResrceNo + "'";

			    if(util.Grid.getRowState(app, "grdCasePlanList", nIdx) == cpr.data.tabledata.RowState.INSERTED) {
			        sCondition = sCondition + " && CASE_PLAN_ROW_INDEX == '" + sRowIdx + "'";
			    } else {
			        sCondition = sCondition + " && SRVC_PVSN_PLAN_NO == '" + sSrvcPvsnPlanNo + "'"; 
			    }
			//    console.log("필터조건 : " + sCondition);

			    objDs.clearFilter();
			    objDs.setFilter(sCondition);
			}

